import{_ as a,o,c as r,a2 as n}from"./chunks/framework.DpXDHk3d.js";const c=JSON.parse('{"title":"3.3 安全电压与安全电流","description":"","frontmatter":{},"headers":[],"relativePath":"electrician/low-voltage-electrician/03-chapter-3-dian-qi-an-quan-ji-chu-zhi-shi/3-3-an-quan-dian-ya-yu-an-quan-dian-liu.md","filePath":"electrician/low-voltage-electrician/03-chapter-3-dian-qi-an-quan-ji-chu-zhi-shi/3-3-an-quan-dian-ya-yu-an-quan-dian-liu.md","lastUpdated":1793095197000}'),i={name:"electrician/low-voltage-electrician/03-chapter-3-dian-qi-an-quan-ji-chu-zhi-shi/3-3-an-quan-dian-ya-yu-an-quan-dian-liu.md"};function l(e,t,s,d,u,h){return o(),r("div",null,[...t[0]||(t[0]=[n('<h1 id="_3-3-安全电压与安全电流" tabindex="-1">3.3 安全电压与安全电流 <a class="header-anchor" href="#_3-3-安全电压与安全电流" aria-label="Permalink to &quot;3.3 安全电压与安全电流&quot;">​</a></h1><h2 id="本节导读" tabindex="-1">本节导读 <a class="header-anchor" href="#本节导读" aria-label="Permalink to &quot;本节导读&quot;">​</a></h2><p>&quot;多少伏才是安全的?&quot;答案不是拍脑袋定的,而是按<strong>人能摆脱的电流界限</strong>反推出来的。这一节讲清安全电流的界限、<strong>安全电压的五个等级(42/36/24/12/6 V)<strong>以及安全电压供电的特殊要求——这是全书的</strong>五星考点</strong>。</p><h2 id="一、安全电流界限" tabindex="-1">一、安全电流界限 <a class="header-anchor" href="#一、安全电流界限" aria-label="Permalink to &quot;一、安全电流界限&quot;">​</a></h2><p><strong>安全电流</strong>:人体能够摆脱而不致危及生命的电流界限。一般认为,工频交流电流<strong>超过 10 mA(摆脱电流)</strong>,人就难以自行挣脱,持续通电就有生命危险。因此把 10 mA 看作安全电流的界限。</p><blockquote><p>需要强调的是:<strong>不存在&quot;绝对安全&quot;的电流</strong>。即便是很小电流,如果通过心脏、持续足够长时间,也可能致命。安全电流、安全电压只是把风险降到可接受的水平。</p></blockquote><h2 id="二、安全电压等级-必背" tabindex="-1">二、安全电压等级(必背!) <a class="header-anchor" href="#二、安全电压等级-必背" aria-label="Permalink to &quot;二、安全电压等级(必背!)&quot;">​</a></h2><p><strong>安全电压</strong>,指为防止触电事故而采用的、由特定电源供电的电压系列。国标 GB 3805-2008 规定的额定值如下:</p><table tabindex="0"><thead><tr><th>等级</th><th>额定电压</th><th>典型使用场合</th></tr></thead><tbody><tr><td>Ⅰ</td><td><strong>42 V</strong></td><td>无高度触电危险的场所(船舶等)</td></tr><tr><td>Ⅱ</td><td><strong>36 V</strong></td><td>一般场所的行灯、机床局部照明、手持电动工具</td></tr><tr><td>Ⅲ</td><td><strong>24 V</strong></td><td>金属容器内、隧道、矿井等潮湿危险场所</td></tr><tr><td>Ⅳ</td><td><strong>12 V</strong></td><td>特别潮湿场所、锅炉房、浴室等</td></tr><tr><td>Ⅴ</td><td><strong>6 V</strong></td><td>水下作业等特殊场合</td></tr></tbody></table><blockquote><p>💡 记忆口诀:<strong>&quot;42、36、24、12、6,越来越危险环境用越来越低电压&quot;</strong>。环境越潮湿、越危险,安全电压越低。</p></blockquote><p><strong>考试常用数字</strong>:</p><ul><li>行灯(手提灯)电压<strong>不得超过 36 V</strong>;</li><li>在金属容器内、特别潮湿场所,照明电压<strong>不得超过 12 V</strong>;</li><li>水下作业用 6 V。</li></ul><h2 id="三、安全电压供电的特殊要求" tabindex="-1">三、安全电压供电的特殊要求 <a class="header-anchor" href="#三、安全电压供电的特殊要求" aria-label="Permalink to &quot;三、安全电压供电的特殊要求&quot;">​</a></h2><p>安全电压不是&quot;用变压器把电压调低&quot;就行,它有严格的供电条件:</p><ol><li><strong>必须由安全隔离变压器(双绕组变压器)供电</strong>——二次绕组与一次绕组间有可靠绝缘隔离;</li><li><strong>不得使用自耦变压器</strong>降压(自耦变压器高低压绕组共用一个绕组,一旦故障会把高压直接串到低压侧,非常危险);</li><li>安全隔离变压器的二次绕组应<strong>采用接地或不接地</strong>的正确接法(按规范);</li><li>安全电压回路中<strong>不得接入</strong>其他电气设备和使用其他电源。</li></ol><blockquote><p>⚠️ 易混点:安全电压 = 安全隔离变压器供电 + 独立回路,不是&quot;随便降压&quot;。</p></blockquote><h2 id="四、为什么-36-v、12-v-就能-安全" tabindex="-1">四、为什么 36 V、12 V 就能&quot;安全&quot; <a class="header-anchor" href="#四、为什么-36-v、12-v-就能-安全" aria-label="Permalink to &quot;四、为什么 36 V、12 V 就能&quot;安全&quot;&quot;">​</a></h2><p>因为安全电压的取值,是围绕**摆脱电流(10 mA)**和人体电阻推算的:例如人体电阻按 1000~2000 Ω 计,<code>10 mA × 2000 Ω = 20 V</code> 左右,留出余量定为 24 V、36 V 等。<strong>电压越高,对应的安全条件要求越高(环境越干燥、场所越不易接触)</strong>。</p><h2 id="五、考点提示" tabindex="-1">五、考点提示 <a class="header-anchor" href="#五、考点提示" aria-label="Permalink to &quot;五、考点提示&quot;">​</a></h2><ul><li>✅ <strong>安全电压额定值:42、36、24、12、6 V</strong>(五个等级,顺序别乱)。</li><li>✅ 行灯电压 ≤ 36 V;金属容器内/特别潮湿场所 ≤ 12 V。</li><li>✅ 安全电压<strong>必须由隔离变压器供电,禁止用自耦变压器</strong>。</li><li>✅ 安全电流界限:工频 <strong>10 mA</strong>(摆脱电流)。</li><li>⚠️ 易混点:安全电压不是&quot;绝对安全&quot;,只是把风险降到可接受水平;等级越高(电压越高)适用的环境越&quot;不危险&quot;。</li></ul><h2 id="六、本节小结" tabindex="-1">六、本节小结 <a class="header-anchor" href="#六、本节小结" aria-label="Permalink to &quot;六、本节小结&quot;">​</a></h2><ul><li>安全电流界限 10 mA;安全电压五个等级 42/36/24/12/6 V。</li><li>环境越危险,用越低的安全电压。</li><li>安全电压由隔离变压器供电,严禁自耦变压器。</li></ul><h2 id="七、自测练习" tabindex="-1">七、自测练习 <a class="header-anchor" href="#七、自测练习" aria-label="Permalink to &quot;七、自测练习&quot;">​</a></h2><ol><li>(单选)安全电压额定值中,不包括下列哪个等级()。 A. 42 V　B. 36 V　C. 24 V　D. 48 V</li><li>(判断)在特别潮湿的场所,行灯电压不得超过 12 V。( )</li><li>(单选)安全电压应由()供电。 A. 自耦变压器　B. 安全隔离变压器　C. 普通降压变压器　D. 任何变压器</li><li>(判断)安全电压是绝对安全的电压,使用安全电压就不会触电。( )</li><li>(单选)一般场所使用的手持照明灯(行灯),电压不得超过()。 A. 6 V　B. 12 V　C. 24 V　D. 36 V</li></ol><details><summary>参考答案(点击展开)</summary><ol><li><strong>D</strong>。安全电压额定值为 42、36、24、12、6 V,没有 48 V。</li><li><strong>√</strong>。特别潮湿、金属容器内等场所,行灯电压不超过 12 V。</li><li><strong>B</strong>。必须由安全隔离变压器(双绕组)供电,禁止用自耦变压器。</li><li><strong>×</strong>。安全电压只是降低风险,并非绝对安全。</li><li><strong>D</strong>。一般场所行灯电压不超过 36 V。</li></ol></details>',25)])])}const q=a(i,[["render",l]]);export{c as __pageData,q as default};
